import asyncioimport hashlibimport hmacimport jsonimport loggingimport osimport timeimport requestsimport websocketsfrom market_data import MarketDataStore, OrderBookStorelogging.basicConfig(    level=logging.INFO,    format="%(message)s",    handlers=[logging.FileHandler("bitmart_futures.log"), logging.StreamHandler()],)log = logging.getLogger()logging.getLogger("httpx").setLevel(logging.WARNING)logging.getLogger("httpcore").setLevel(logging.WARNING)DEMO_TRADING = TruePROD_PUBLIC_WS = "wss://openapi-ws-v2.bitmart.com/api?protocol=1.1"PROD_PRIVATE_WS = "wss://openapi-ws-v2.bitmart.com/user?protocol=1.1"DEMO_PUBLIC_WS = "wss://openapi-wsdemo-v2.bitmart.com/api?protocol=1.1"DEMO_PRIVATE_WS = "wss://openapi-wsdemo-v2.bitmart.com/user?protocol=1.1"PUBLIC_WS_URL = DEMO_PUBLIC_WS if DEMO_TRADING else PROD_PUBLIC_WSPRIVATE_WS_URL = DEMO_PRIVATE_WS if DEMO_TRADING else PROD_PRIVATE_WSPING_INTERVAL_SEC = 15RECONNECT_BASE_DELAY_SEC = 3RECONNECT_MAX_DELAY_SEC = 60HEARTBEAT_INTERVAL_SEC = 30TICKER_CHANNEL = "futures/ticker"DEPTH_LEVELS = 20SYMBOLS = ["BTCUSDT", "ETHUSDT", "SOLUSDT"]DEPTH_CHANNEL_PREFIX = f"futures/depth{DEPTH_LEVELS}:"DEPTH_CHANNELS = [f"{DEPTH_CHANNEL_PREFIX}{symbol}" for symbol in SYMBOLS]def _load_db_config() -> dict:    here = os.path.dirname(os.path.abspath(__file__))    candidates = [        os.path.join(here, "db.txt"),        os.path.join(os.path.dirname(here), "db.txt"),    ]    for path in candidates:        if os.path.exists(path):            config = {}            with open(path, "r") as f:                for line in f:                    line = line.strip()                    if not line or line.startswith("#"):                        continue                    if "=" in line:                        k, _, v = line.partition("=")                        config[k.strip()] = v.strip().strip('"')            return config    raise FileNotFoundError(f"db.txt not found in any of: {candidates}")def _clean_secret(value):    if value is None:        return None    if isinstance(value, str):        value = value.strip()        if value.upper() in ("", "NULL"):            return None    return valuedef load_bitmart_credentials() -> dict:    from supabase import create_client    config = _load_db_config()    sb = create_client(config["SUPABASE_URL"], config["SUPABASE_KEY"])    rows = sb.table("api_keys").select("*").execute()    match = next(        (r for r in rows.data or [] if (r.get("exchange_name") or "").strip().lower() == "bitmart"),        None,    )    if not match:        raise RuntimeError("No 'BitMart' row found in the api_keys Supabase table")    api_key = _clean_secret(match.get("api_key"))    api_secret = _clean_secret(match.get("api_secret"))    memo = _clean_secret(match.get("memo"))    missing = [n for n, v in (("api_key", api_key), ("api_secret", api_secret), ("memo", memo)) if not v]    if missing:        raise RuntimeError(f"BitMart credentials incomplete in Supabase — missing: {', '.join(missing)}")    return {"api_key": api_key, "api_secret": api_secret, "memo": memo}def get_outbound_ip():    try:        resp = requests.get("https://api.ipify.org?format=json", timeout=5)        return resp.json().get("ip")    except Exception:        return Nonedef build_login_sign(timestamp_ms: str, memo: str, api_secret: str) -> str:    payload = f"{timestamp_ms}#{memo}#bitmart.WebSocket"    return hmac.new(api_secret.encode(), payload.encode(), hashlib.sha256).hexdigest()async def _keepalive(ws):    while True:        await asyncio.sleep(PING_INTERVAL_SEC)        try:            await ws.send(json.dumps({"action": "ping"}))        except Exception:            returnasync def run_public(market_data: MarketDataStore, order_book: OrderBookStore):    delay = RECONNECT_BASE_DELAY_SEC    while True:        try:            log.info(f"[public] connecting to {PUBLIC_WS_URL}")            async with websockets.connect(PUBLIC_WS_URL, ping_interval=None) as ws:                log.info("[public] connected")                delay = RECONNECT_BASE_DELAY_SEC                await ws.send(json.dumps({"action": "subscribe", "args": [TICKER_CHANNEL, *DEPTH_CHANNELS]}))                keepalive_task = asyncio.create_task(_keepalive(ws))                try:                    async for raw in ws:                        if raw == "pong":                            continue                        try:                            msg = json.loads(raw)                        except json.JSONDecodeError:                            log.warning(f"[public] non-JSON message: {raw[:200]}")                            continue                        group = msg.get("group", "")                        if msg.get("action") == "subscribe":                            if msg.get("success"):                                log.info(f"[public] \u2705 subscribed to {msg.get('group')}")                            else:                                log.error(f"[public] \u274c subscribe failed: {msg}")                        elif group == TICKER_CHANNEL:                            await market_data.update_from_ticker(msg.get("data") or {})                        elif group.startswith(DEPTH_CHANNEL_PREFIX):                            await order_book.apply_depth_update(msg.get("data") or {})                finally:                    keepalive_task.cancel()        except Exception as e:            log.error(f"[public] connection error: {type(e).__name__}: {str(e)[:200]} \u2014 reconnecting in {delay}s")            await asyncio.sleep(delay)            delay = min(delay * 2, RECONNECT_MAX_DELAY_SEC)async def run_heartbeat(market_data: MarketDataStore, order_book: OrderBookStore):    while True:        await asyncio.sleep(HEARTBEAT_INTERVAL_SEC)        symbol_count = await market_data.symbol_count()        book_count = len(await order_book.symbols())        log.info(f"[heartbeat] tracking {symbol_count} tickers, {book_count} order books")async def run_private(creds: dict):    delay = RECONNECT_BASE_DELAY_SEC    memo = creds["memo"]    while True:        try:            log.info(f"[private] connecting to {PRIVATE_WS_URL}")            async with websockets.connect(PRIVATE_WS_URL, ping_interval=None) as ws:                log.info("[private] connected \u2014 logging in")                delay = RECONNECT_BASE_DELAY_SEC                timestamp_ms = str(int(time.time() * 1000))                sign = build_login_sign(timestamp_ms, memo, creds["api_secret"])                login_msg = {"action": "access", "args": [creds["api_key"], timestamp_ms, sign, "web"]}                await ws.send(json.dumps(login_msg))                keepalive_task = asyncio.create_task(_keepalive(ws))                try:                    async for raw in ws:                        if raw == "pong":                            continue                        try:                            msg = json.loads(raw)                        except json.JSONDecodeError:                            log.warning(f"[private] non-JSON message: {raw[:200]}")                            continue                        if msg.get("action") == "access":                            if msg.get("success"):                                log.info("[private] \u2705 login successful")                            else:                                log.error(f"[private] \u274c login failed: {msg}")                                log.error("[private] if this key requires IP whitelisting, confirm this machine's outbound IP is whitelisted on BitMart")                                await asyncio.sleep(RECONNECT_MAX_DELAY_SEC)                        elif msg.get("group") == "System":                            continue                        else:                            log.info(f"[private] message: {msg}")                finally:                    keepalive_task.cancel()        except Exception as e:            log.error(f"[private] connection error: {type(e).__name__}: {str(e)[:200]} \u2014 reconnecting in {delay}s")            await asyncio.sleep(delay)            delay = min(delay * 2, RECONNECT_MAX_DELAY_SEC)async def main():    creds = load_bitmart_credentials()    outbound_ip = get_outbound_ip()    log.info(f"Outbound IP for this machine: {outbound_ip or 'could not determine'}")    log.info(f"Starting BitMart Futures bot (demo_trading={DEMO_TRADING})")    market_data = MarketDataStore()    order_book = OrderBookStore(depth_levels=DEPTH_LEVELS)    await asyncio.gather(        run_public(market_data, order_book),        run_private(creds),        run_heartbeat(market_data, order_book),    )if __name__ == "__main__":    try:        asyncio.run(main())    except KeyboardInterrupt:        log.info("bitmart_futures.py stopped.")